// Only process offer emails from the pharmacy's offers mailbox; anything
// else landing in the inbox is ignored.
const OFFERS_SENDER = 'farmaciaalbinyana@gmail.com';

// Each offer email body is a table of rows, one offer per line:
// "<start> A <end>\t<brand>\t<description>" (tab-separated; some clients
// send runs of spaces instead of tabs). Blank lines between rows are skipped.
// Turns each valid row into one output item carrying a ready-to-send prompt.
const results = [];

for (const item of $input.all()) {
  const from = item.json.from?.text || item.json.from?.value?.[0]?.address || '';
  if (!from.toLowerCase().includes(OFFERS_SENDER)) continue;

  const body = item.json.textPlain || item.json.text || '';
  const lines = body.split(/\r?\n/);

  for (const line of lines) {
    if (!line.trim()) continue;

    let parts = line.split('\t').map((p) => p.trim()).filter(Boolean);
    if (parts.length < 3) {
      parts = line.split(/\s{2,}/).map((p) => p.trim()).filter(Boolean);
    }
    if (parts.length < 3) continue;

    const [dateRange, brand, ...descriptionParts] = parts;
    const description = descriptionParts.join(' ');

    const dateMatch = dateRange.match(
      /(\d{1,2}\/\d{1,2}\/\d{2,4})\s*A\s*(\d{1,2}\/\d{1,2}\/\d{2,4})/i,
    );
    if (!dateMatch) continue;
    const [, startDate, endDate] = dateMatch;

    results.push({
      json: {
        brand,
        startDate,
        endDate,
        description,
        prompt:
          `Add or update this promotional offer on the offers page:\n` +
          `- Brand: ${brand}\n` +
          `- Valid: ${startDate} to ${endDate}\n` +
          `- Details: ${description}\n\n` +
          `If an offer for this brand with overlapping dates already exists, update it instead of creating a duplicate.`,
        subject: `Offer: ${brand} (${startDate}-${endDate})`,
      },
    });
  }
}

return results;
